"""state-vc-reporting: builds the dashboards, Power BI kit and docs from the anonymised data in data/processed/.
python src/build.py"""
import sys, re, glob, warnings
from pathlib import Path
import numpy as np, pandas as pd, openpyxl
warnings.filterwarnings("ignore")
ROOT = Path(__file__).resolve().parents[1]; PROC = ROOT / "data" / "processed"; sys.path.insert(0, str(Path(__file__).parent))
from scaffold import Project, PALETTE
key = lambda s: re.sub(r"[^a-z]", "", str(s).lower())

rd = lambda n: pd.read_csv(PROC / n)
au, ep, tg, tl, wa, we, cpd, cpe = [rd(n) for n in ["audit_progress_district.csv", "epacs_progress_district.csv", "epacs_targets_dec2025.csv", "state_timeline.csv", "weekly_audit_target_6nov.csv", "weekly_epacs_target_6nov.csv", "cert_pending_district_25jan2026.csv", "cert_expected_dates_25jan2026.csv"]]
tv = lambda m, s, d: float(tl[(tl.measure == m) & (tl.source == s) & (tl.date == d)].value.iloc[0])
P = Project(ROOT, "state-vc-reporting", "State VC Reporting: PACS Computerization, State A",
            "The weekly video-conference review pack for the State: audit and year-end progress, e-PACS completion and certification, dated targets, and certification-pending PACS, by district.",
            banner="Illustrative data: names are pseudonymised and counts are rescaled. The reporting design, KPIs and method are real; the numbers are not.",
            footer="Anonymised portfolio edition. Do not use these figures for decisions.")
a3, a20 = tv("Audit", "4-Dec deck", "2025-12-03"), tv("Audit", "4-Dec deck", "2025-11-20"); a18 = tv("Audit", "18-Dec deck", "2025-12-18"); e3, e20 = tv("e-PACS completed", "4-Dec deck", "2025-12-03"), tv("e-PACS completed", "4-Dec deck", "2025-11-20")
c18, c14 = tv("e-PACS certificates", "18-Dec deck", "2025-12-18"), tv("e-PACS certificates", "18-Dec deck", "2025-11-14")
k1 = P.kpi("Audit and YEP completed (3-Dec-2025)", a3, "int", "PACS with audit completed on 3-Dec-2025 (4-Dec deck)", "Sum of district audit completed", 'CALCULATE(SUM(audit_progress_district[audit_3dec]))', "VC review deck 4-Dec-2025", "cooperative registrar, Audit dept, development finance partner", home=True)
k2 = P.kpi("Audit completion (3-Dec-2025)", 100 * a3 / au.total_pacs.sum(), "pct1", "Audit completed as share of all PACS", "Audit completed / Total PACS", "DIVIDE(SUM(audit_progress_district[audit_3dec]), SUM(audit_progress_district[total_pacs]))", "VC review deck 4-Dec-2025", "cooperative registrar, Audit dept", home=True)
k3 = P.kpi("Audit gain in two weeks", a3 - a20, "int", "Increase in audit completed between 20-Nov and 3-Dec", "Audit(3-Dec) - Audit(20-Nov)", "SUM(audit_progress_district[audit_3dec]) - SUM(audit_progress_district[audit_20nov])", "VC review deck 4-Dec-2025", "cooperative registrar, Collector")
k4 = P.kpi("Audit completion (18-Dec-2025)", 100 * a18 / au.total_pacs_dec18.sum(), "pct1", "Audit completed as share of all PACS (18-Dec deck, different base)", "Audit completed / Total PACS", "DIVIDE(SUM(audit_progress_district[audit_18dec]), SUM(audit_progress_district[total_pacs_dec18]))", "Working presentation 18-Dec-2025", "cooperative registrar, development finance partner", tone="good", home=True)
k5 = P.kpi("e-PACS completed (3-Dec-2025)", e3, "int", "PACS with e-PACS completed on 3-Dec-2025 (4-Dec deck)", "Sum of district e-PACS completed", "SUM(epacs_progress_district[epacs_3dec])", "VC review deck 4-Dec-2025", "cooperative registrar, development finance partner", home=True)
k6 = P.kpi("e-PACS certificates (18-Dec-2025)", c18, "int", "Certificates issued up to 18-Dec-2025 (18-Dec deck)", "Sum of district certificates", "SUM(epacs_progress_district[cert_18dec])", "Working presentation 18-Dec-2025", "development finance partner, cooperative registrar")
k7 = P.kpi("e-PACS certificate growth", c18 - c14, "int", "Certificates added between 14-Nov and 18-Dec-2025", "Cert(18-Dec) - Cert(14-Nov)", "SUM(epacs_progress_district[cert_18dec]) - SUM(epacs_progress_district[cert_14nov])", "Working presentation 18-Dec-2025", "development finance partner, cooperative registrar")
k8 = P.kpi("PACS pending e-PACS certificate (25-Jan-2026)", int(cpd.certificate_pending.sum()), "int", "PACS on the pending list without a certificate", "Listed - Received", "SUM(cert_pending_district_25jan2026[certificate_pending])", "Source tracker", "development finance partner, Collector", tone="bad", home=True)
k9 = P.kpi("Week-1 e-PACS target achieved (6-Nov-2025)", 100 * we.w1_ach.sum() / we.w1_target.sum(), "pct1", "Week-1 achievement against week-1 target", "Achieved / Target", "DIVIDE(SUM(weekly_epacs_target_6nov[w1_ach]), SUM(weekly_epacs_target_6nov[w1_target]))", "Source tracker", "cooperative registrar, development finance partner", tone="bad")
for n, d, ds, g in [("audit_progress_district", au, "Audit completed by district on 14-Nov, 20-Nov, 26-Nov, 3-Dec and 18-Dec 2025", "district"), ("epacs_progress_district", ep, "e-PACS completed and certificates by district", "district"), ("epacs_targets_dec2025", tg, "Dated e-PACS targets by district, Nov-Dec 2025", "district"),
                    ("state_timeline", tl, "State totals per measure, source deck and date", "measure x source x date"), ("weekly_audit_target_6nov", wa, "Audit weekly target and achievement, 6-Nov-2025", "district"), ("weekly_epacs_target_6nov", we, "e-PACS weekly target and achievement, 6-Nov-2025", "district"),
                    ("cert_pending_district_25jan2026", cpd, "PACS awaiting e-PACS certificate, by district, 25-Jan-2026", "district"), ("cert_expected_dates_25jan2026", cpe, "Expected certificate dates (count of PACS per date)", "date")]: P.table(n, d, ds, g)
P.relationships = ["Join `audit_progress_district[district]`, `epacs_progress_district[district]`, `epacs_targets_dec2025[district]`, `weekly_*[district]` and `cert_pending_district_25jan2026[district]` to a `dim_district` table (distinct district names) on district; use dim_district for slicers.", "`state_timeline` is standalone: filter on `measure` and plot `value` by `date`, with `source` as legend (definitions differ between decks)."]
P.sources = [("Weekly VC review decks (PowerPoint)", "Audit and e-PACS comparisons, dated targets"), ("Working presentation (PowerPoint)", "Audit and certificates at two dates"), ("Weekly target workbook (Excel)", "Weekly audit and e-PACS targets and achievement"), ("Certification-pending list (Excel)", "Pending certificates by district, aggregated")]

P.exclusions = ["Real district, branch and bank names (replaced by pseudonyms).", "Original source files, PACS-level extracts, names, contact details and credentials.", "Real counts: all counts are rescaled, so absolute numbers are illustrative."]

P.assumptions = ["Two review decks use different bases and definitions, so audit and e-PACS series are plotted per source and not merged.", "e-PACS completed and e-PACS certificates are different measures.", "Expected certificate dates are parsed from free text; unreadable dates are counted as no expected date."]

pal = {"4-Dec deck": PALETTE[0], "18-Dec deck": PALETTE[1]}
def tline(measure):
    t = tl[tl.measure == measure].sort_values("date"); labs = sorted(t.date.unique())
    return dict(labels=[d[5:] for d in labs], series=[dict(name=s, values=[(float(x.value.iloc[0]) if len(x) else None) for d in labs for x in [t[(t.source == s) & (t.date == d)]]], color=pal.get(s, PALETTE[2])) for s in t.source.unique()])
au["audit_pct_3dec"] = 100 * au.audit_3dec / au.total_pacs; au["gain"] = au.audit_3dec - au.audit_20nov; au["rem18"] = au.audit_remaining_18dec
P.page("audit", "Audit and YEP progress", "State and district audit completion across the 20-Nov to 18-Dec review dates.", [
    {"type": "kpis", "items": [k1, k2, k3, k4]},
    dict(type="line", title="Audit completed: state total by review date", w="half", src="state_timeline", note="Each line is one deck; the two decks use different bases, so compare within a line.", **tline("Audit")),
    {"type": "hbars", "title": "Largest audit gain, 20-Nov to 3-Dec", "w": "half", "src": "audit_progress_district", "rows": [dict(label=r.district, value=int(r.gain)) for r in au.sort_values("gain", ascending=False).head(10).itertuples()], "color": "var(--c1)"},
    {"type": "hbars", "title": "Most PACS still pending audit (18-Dec)", "w": "half", "src": "audit_progress_district", "rows": [dict(label=r.district, value=int(r.rem18)) for r in au.sort_values("rem18", ascending=False).head(10).itertuples() if r.rem18 > 0], "color": "var(--c3)"},
    {"type": "table", "title": "District table", "src": "audit_progress_district", "search": "district", "cols": [dict(key="district", label="District"), dict(key="total_pacs", label="PACS", fmt="int"), dict(key="audit_20nov", label="20-Nov", fmt="int"), dict(key="audit_3dec", label="3-Dec", fmt="int"), dict(key="audit_pct_3dec", label="% 3-Dec", fmt="pct1", heat=dict(lo=60, hi=95)), dict(key="audit_18dec", label="18-Dec", fmt="int"), dict(key="audit_remaining_18dec", label="Left 18-Dec", fmt="int")], "rows": au.round(1).fillna("").to_dict("records"), "sort": "audit_pct_3dec", "dir": 1, "maxh": 420}], tags=["cooperative registrar", "Audit dept", "development finance partner"])
ep["gain"] = ep.epacs_3dec - ep.epacs_20nov; ep["cert_gain"] = ep.cert_18dec - ep.cert_14nov
t4 = tg[["t_27nov", "t_4dec", "t_11dec", "t_15dec"]].sum()
P.page("epacs", "e-PACS completion and certification", "e-PACS completed (4-Dec deck) and certificates issued (18-Dec deck) by district, with the dated Dec-2025 targets.", [
    {"type": "kpis", "items": [k5, k6, k7]},
    dict(type="line", title="e-PACS completed (state)", w="half", src="state_timeline", **tline("e-PACS completed")),
    dict(type="line", title="e-PACS certificates (state)", w="half", src="state_timeline", **tline("e-PACS certificates")),
    {"type": "hbars", "title": "Dated targets: PACS due on each date (all PACS)", "w": "half", "src": "epacs_targets_dec2025", "rows": [dict(label=l, value=int(t4[c])) for l, c in [("27 Nov: dynamic day-end", "t_27nov"), ("4 Dec: Apr-Oct 2025 day-end", "t_4dec"), ("11 Dec: March 2025 day-end", "t_11dec"), ("15 Dec: Mar 2024-Feb 2025", "t_15dec")]], "color": "var(--c4)"},
    {"type": "hbars", "title": "Largest certificate growth, 14-Nov to 18-Dec", "w": "half", "src": "epacs_progress_district", "rows": [dict(label=r.district, value=int(r.cert_gain)) for r in ep.sort_values("cert_gain", ascending=False).head(10).itertuples()]},
    {"type": "table", "title": "District table", "src": "epacs_progress_district", "search": "district", "cols": [dict(key="district", label="District"), dict(key="total_pacs", label="PACS", fmt="int"), dict(key="epacs_20nov", label="e-PACS 20-Nov", fmt="int"), dict(key="epacs_3dec", label="e-PACS 3-Dec", fmt="int"), dict(key="gain", label="Gain", fmt="signed"), dict(key="cert_14nov", label="Cert 14-Nov", fmt="int"), dict(key="cert_18dec", label="Cert 18-Dec", fmt="int"), dict(key="cert_gain", label="Cert gain", fmt="signed")], "rows": ep.fillna("").to_dict("records"), "sort": "cert_gain", "maxh": 420}], tags=["development finance partner", "cooperative registrar"])
we["pct_w1"] = 100 * we.w1_ach / we.w1_target.replace(0, np.nan); wa["pct_w1"] = 100 * wa.w1_ach / wa.w1_target.replace(0, np.nan)
P.page("weekly-targets", "Weekly targets (6-Nov-2025)", "The week-1 plan for audit and e-PACS by district and how much was achieved.", [
    {"type": "kpis", "items": [k9, dict(label="Audit week-1 achieved", value=f"{100 * wa.w1_ach.sum() / wa.w1_target.sum():.1f}%", tone="bad"), dict(label="Audit & YEP done (6-Nov)", value=f"{100 * wa.total_audit.sum() / wa.total.sum():.1f}%")]},
    {"type": "hbars", "title": "e-PACS: largest week-1 shortfall", "w": "half", "src": "weekly_epacs_target_6nov", "rows": [dict(label=r.district, value=round(r.w1_extra)) for r in we.sort_values("w1_extra", ascending=False).head(10).itertuples()], "color": "var(--c3)"},
    {"type": "hbars", "title": "Audit: largest week-1 shortfall", "w": "half", "src": "weekly_audit_target_6nov", "rows": [dict(label=r.district, value=round(max(0, r.w1_target - r.w1_ach))) for r in wa.assign(s=wa.w1_target - wa.w1_ach).sort_values("s", ascending=False).head(10).itertuples()], "color": "var(--c2)"},
    {"type": "table", "title": "e-PACS weekly target by district", "w": "half", "src": "weekly_epacs_target_6nov", "search": "district", "cols": [dict(key="district", label="District"), dict(key="total", label="PACS", fmt="int"), dict(key="certified", label="Certified", fmt="int"), dict(key="w1_target", label="Wk-1 target", fmt="dec0"), dict(key="w1_ach", label="Achieved", fmt="int"), dict(key="pct_w1", label="% of target", fmt="pct0", heat=dict(lo=20, hi=80))], "rows": we.round(1).fillna("").to_dict("records"), "sort": "pct_w1", "dir": 1, "maxh": 380},
    {"type": "table", "title": "Audit weekly target by district", "w": "half", "src": "weekly_audit_target_6nov", "search": "district", "cols": [dict(key="district", label="District"), dict(key="total", label="PACS", fmt="int"), dict(key="pct_done", label="% done", fmt="pct1", heat=dict(lo=60, hi=95)), dict(key="remaining", label="Remaining", fmt="int"), dict(key="w1_target", label="Wk-1 target", fmt="dec0"), dict(key="w1_ach", label="Achieved", fmt="int")], "rows": wa.round(1).fillna("").to_dict("records"), "sort": "pct_done", "dir": 1, "maxh": 380}], tags=["cooperative registrar", "development finance partner"])
P.page("cert-pending", "Certification pending (25-Jan-2026)", "PACS still waiting for their e-PACS certificate on 25-Jan-2026, with expected dates. District totals only.", [
    {"type": "kpis", "items": [k8, dict(label="Districts with pending PACS", value=str(int((cpd.certificate_pending > 0).sum()))), dict(label="PACS with no expected date", value=str(int(cpd.no_expected_date.sum())), tone="bad")]},
    {"type": "hbars", "title": "Pending PACS by district", "w": "half", "src": "cert_pending_district_25jan2026", "rows": [dict(label=r.district, value=int(r.certificate_pending)) for r in cpd.sort_values("certificate_pending", ascending=False).head(12).itertuples()], "color": "var(--c3)"},
    {"type": "hbars", "title": "Expected certificate date (PACS per date)", "w": "half", "src": "cert_expected_dates_25jan2026", "rows": [dict(label=r.expected, value=int(r.pacs)) for r in cpe.sort_values("expected").itertuples()], "color": "var(--c4)"}], tags=["development finance partner", "Collector"])
P.page("slide-pack", "VC slide pack: formats and KPIs", "The standard slides used in the weekly State VC, the KPI each slide carries and the dashboard page that reproduces it.", [
    {"type": "table", "title": "Slide formats", "cols": [dict(key="slide", label="Slide"), dict(key="kpi", label="KPI / table"), dict(key="audience", label="Audience"), dict(key="page", label="Dashboard page")], "sort": "slide", "dir": 1, "rows": [
        dict(slide="Overall progress: entry and day-end", kpi="PACS by group, day-end current, entry gap", audience="Collector, cooperative registrar", page="PACS Status project"), dict(slide="Audit comparison chart", kpi="Audit completed on three dates and growth, by district", audience="cooperative registrar, Audit dept", page="Audit and YEP progress"),
        dict(slide="100% audit districts / audit pending", kpi="Districts at 100%; pending PACS and audit-ready PACS", audience="cooperative registrar", page="Audit and YEP progress"), dict(slide="e-PACS comparison chart", kpi="e-PACS completed on three dates, by district", audience="development finance partner, cooperative registrar", page="e-PACS completion"),
        dict(slide="e-PACS targets", kpi="PACS due on each deadline, by district", audience="Collector", page="e-PACS completion"), dict(slide="Weekly target vs achievement", kpi="Week-1 target, achieved, still needed", audience="cooperative registrar, development finance partner", page="Weekly targets"),
        dict(slide="Working / not working PACS", kpi="Working PACS % by district", audience="Collector", page="PACS Status project"), dict(slide="Laggard PACS", kpi="Entry and day-end on or before 31-Mar-2025", audience="Collector, district cooperative bank", page="PACS Status project"),
        dict(slide="Certification pending", kpi="PACS without certificate and expected date", audience="development finance partner", page="Certification pending")]}], tags=["Reference"])
P.build()
